use serde_json::json;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = String::new();
    let mut hex = String::new();

    for byte in input.as_array().unwrap().iter() {
        let byte_str = byte.to_string();
        let byte_int = byte_str.parse::<i64>().unwrap();

        if byte_int < 16 {
            hex.push_str(&format!("{:02x}", byte_int));
        } else {
            hex.push_str(&format!("{:02x}", byte_int - 16));
        }

        result.push_str(&format!("{:02x}", byte_int));
    }

    json!(json!(hex))
}
